mod lab9 {
mod solution {
pub fn counts(words: &[&str]) -> std::collections::BTreeMap<String, usize> {
    let mut counts = std::collections::BTreeMap::new();
    for word in words { *counts.entry((*word).to_owned()).or_insert(0) += 1; }
    counts
}

}

pub fn verify() {
    assert_eq!(solution::counts(&["rust", "crab", "rust"]), std::collections::BTreeMap::from([("crab".to_owned(), 1), ("rust".to_owned(), 2)]), "case 1");
    assert_eq!(solution::counts(&[]), std::collections::BTreeMap::new(), "case 2");
    assert_eq!(solution::counts(&["a", "a", "a"]), std::collections::BTreeMap::from([("a".to_owned(), 3)]), "case 3");

    println!("PASS collections");
}

