mod lab18 {
mod solution {
pub fn total<R: std::io::BufRead>(reader: R) -> Result<i64, String> {
    let mut sum = 0i64;
    for (index, line) in reader.lines().enumerate() {
        let line = line.map_err(|_| "read failed".to_owned())?;
        if line.trim().is_empty() { continue; }
        let n: i64 = line.trim().parse().map_err(|_| format!("line {}", index + 1))?;
        sum = sum.checked_add(n).ok_or_else(|| "overflow".to_owned())?;
    }
    Ok(sum)
}

}
struct Broken;
impl std::io::Read for Broken {
    fn read(&mut self, _: &mut [u8]) -> std::io::Result<usize> { Err(std::io::Error::other("broken")) }
}
pub fn verify() {
    assert_eq!(solution::total(std::io::Cursor::new("12\n\n8\n")), Ok(20), "case 1");
    assert_eq!(solution::total(std::io::Cursor::new("")), Ok(0), "case 2");
    assert_eq!(solution::total(std::io::Cursor::new("\nnope")), Err("line 2".to_owned()), "case 3");
    assert_eq!(solution::total(std::io::Cursor::new("9223372036854775807\n1")), Err("overflow".to_owned()), "case 4");
    assert_eq!(solution::total(std::io::Cursor::new("-4\r\n 2 ")), Ok(-2), "case 5");
    assert_eq!(solution::total(std::io::BufReader::new(Broken)), Err("read failed".to_owned()));
    println!("PASS buffered-line-input");
}

}
mod lab19 {
mod solution {
pub fn destination(root: &std::path::Path, name: &std::path::Path) -> Option<std::path::PathBuf> {
    let mut relative = std::path::PathBuf::new();
    for component in name.components() {
        match component {
            std::path::Component::Normal(part) => relative.push(part),
            std::path::Component::CurDir => {},
            _ => return None,
        }
    }
    if relative.as_os_str().is_empty() { None } else { Some(root.join(relative)) }
}

}

pub fn verify() {
    assert_eq!(solution::destination(std::path::Path::new("root"), std::path::Path::new("reports/day.txt")), Some(std::path::PathBuf::from("root/reports/day.txt")), "case 1");
    assert_eq!(solution::destination(std::path::Path::new("root"), std::path::Path::new("../x")), None, "case 2");
    assert_eq!(solution::destination(std::path::Path::new("root"), std::path::Path::new("/x")), None, "case 3");
    assert_eq!(solution::destination(std::path::Path::new("root"), std::path::Path::new(".")), None, "case 4");
    assert_eq!(solution::destination(std::path::Path::new("root"), std::path::Path::new("./résumé.txt")), Some(std::path::PathBuf::from("root/résumé.txt")), "case 5");

    println!("PASS paths-and-boundaries");
}

}
mod lab20 {
mod solution {
pub fn save_report(path: &std::path::Path, text: &str) -> std::io::Result<String> {
    std::fs::write(path, text)?;
    std::fs::read_to_string(path)
}

}

pub fn verify() {
