mod lab25 {
mod solution {
pub fn canonical(mut ids: Vec<i32>) -> Vec<i32> {
    ids.sort_unstable();
    ids.dedup();
    ids
}

}

pub fn verify() {
    assert_eq!(solution::canonical(vec![3, 1, 3]), vec![1, 3], "case 1");
    assert_eq!(solution::canonical(vec![]), vec![], "case 2");
    assert_eq!(solution::canonical(vec![-2, 0, -2, 4]), vec![-2, 0, 4], "case 3");
    assert_eq!(solution::canonical(vec![5, 5, 5]), vec![5], "case 4");
    assert_eq!(solution::canonical(vec![i32::MAX, i32::MIN, 0]), vec![i32::MIN, 0, i32::MAX], "case 5");
    for a in -2..=2 { for b in -2..=2 { for c in -2..=2 {
        let input = vec![a, b, c, a];
        let oracle: Vec<_> = input.iter().copied().collect::<std::collections::BTreeSet<_>>().into_iter().collect();
        let actual = solution::canonical(input);
        assert_eq!(actual, oracle);
        assert_eq!(solution::canonical(actual.clone()), actual);
    } } }
    println!("PASS properties-and-oracles");
}

}
mod lab26 {
mod solution {
pub fn pair(text: &str) -> Option<(u8, u8)> {
    fn byte(s: &str) -> Option<u8> {
        let s = s.trim();
        if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) { return None; }
        s.parse().ok()
    }
    let (left, right) = text.split_once(':')?;
    Some((byte(left)?, byte(right)?))
}

}

pub fn verify() {
    assert_eq!(solution::pair("12:34"), Some((12, 34)), "case 1");
    assert_eq!(solution::pair(" 0 : 255 "), Some((0, 255)), "case 2");
    assert_eq!(solution::pair("1:2:3"), None, "case 3");
    assert_eq!(solution::pair("256:0"), None, "case 4");
    assert_eq!(solution::pair("-1:2"), None, "case 5");
    assert_eq!(solution::pair("+1:2"), None, "case 6");
    assert_eq!(solution::pair(":2"), None, "case 7");
    assert_eq!(solution::pair("１:2"), None, "case 8");

    println!("PASS hostile-parser-inputs");
}

}
