mod lab29 {
mod solution {
pub fn window(memory: &[u8], offset: usize, len: usize) -> Option<&[u8]> {
    let end = offset.checked_add(len)?;
    memory.get(offset..end)
}

}

pub fn verify() {
    assert_eq!(solution::window(b"crab", 1, 2), Some(&b"ra"[..]), "case 1");
