    assert_eq!(solution::window(b"crab", usize::MAX, 2), None, "case 4");
    assert_eq!(solution::window(b"crab", 3, 2), None, "case 5");

    println!("PASS wasm-linear-memory");
}

}
mod lab30 {
mod solution {
pub fn reserve(used: usize, next: usize, limit: usize) -> Option<usize> {
    let total = used.checked_add(next)?;
    (total <= limit).then_some(total)
}

}

pub fn verify() {
    assert_eq!(solution::reserve(8, 2, 10), Some(10), "case 1");
    assert_eq!(solution::reserve(10, 0, 10), Some(10), "case 2");
    assert_eq!(solution::reserve(8, 3, 10), None, "case 3");
    assert_eq!(solution::reserve(11, 0, 10), None, "case 4");
    assert_eq!(solution::reserve(usize::MAX, 1, usize::MAX), None, "case 5");

    println!("PASS runtime-resource-budgets");
}

